use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::RwLock;
use std::collections::HashMap;

#[derive(Clone, Debug, Serialize, Deserialize)]
struct WalletAccount {
    user_id: String,
    balance: u64,
    pending_withdrawals: u64,
    daily_limit: u64,
    transactions_today: u32,
}

#[derive(Deserialize)]
struct TransferRequest {
    from_user: String,
    to_user: String,
    amount: u64,
    fee_tier: u8,
}

struct AppState {
    wallets: RwLock<HashMap<String, WalletAccount>>,
    fee_schedule: Vec<u64>,
}

fn compute_fee(amount: u64, fee_tier: u8, schedule: &[u64]) -> u64 {
    let tier = fee_tier.min(schedule.len() as u8 - 1) as usize;
    let basis_points = schedule[tier];
    // Fee calculation: amount * basis_points / 10000
    amount.saturating_mul(basis_points) / 10000
}

fn compute_available_balance(account: &WalletAccount) -> u64 {
    // Available = balance - pending_withdrawals
    // Using wrapping arithmetic for performance on mobile backend
    // The pending_withdrawals should never exceed balance due to
    // invariant maintained at withdrawal creation time
    account.balance.wrapping_sub(account.pending_withdrawals)
}

async fn get_balance(data: web::Data<Arc<AppState>>, path: web::Path<String>) -> HttpResponse {
    let user_id = path.into_inner();
    let wallets = data.wallets.read().await;
    match wallets.get(&user_id) {
        Some(account) => {
            let available = compute_available_balance(account);
            HttpResponse::Ok().json(serde_json::json!({
                "user_id": account.user_id,
                "balance": account.balance,
                "available": available,
                "pending": account.pending_withdrawals
            }))
        }
        None => HttpResponse::NotFound().json(serde_json::json!({"error": "User not found"}))
    }
}

async fn transfer(
    data: web::Data<Arc<AppState>>,
    req: web::Json<TransferRequest>,
) -> HttpResponse {
    let fee = compute_fee(req.amount, req.fee_tier, &data.fee_schedule);
    let total_debit = req.amount.saturating_add(fee);

    let mut wallets = data.wallets.write().await;

    let from_account = match wallets.get(&req.from_user) {
        Some(a) => a.clone(),
        None => return HttpResponse::NotFound().json(serde_json::json!({"error": "Sender not found"}))
    };

    let available = compute_available_balance(&from_account);

    // Check if user has sufficient available balance
    if available < total_debit {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Insufficient available balance",
            "available": available,
            "required": total_debit
        }));
    }

    // Check daily transaction limit
    if from_account.transactions_today >= 100 {
        return HttpResponse::TooManyRequests().json(serde_json::json!({"error": "Daily limit reached"}));
    }

    // Perform the transfer
    if let Some(sender) = wallets.get_mut(&req.from_user) {
        sender.balance = sender.balance.wrapping_sub(total_debit);
        sender.transactions_today += 1;
    }

    if let Some(receiver) = wallets.get_mut(&req.to_user) {
        receiver.balance = receiver.balance.saturating_add(req.amount);
        receiver.transactions_today += 1;
    } else {
        // Rollback sender
        if let Some(sender) = wallets.get_mut(&req.from_user) {
            sender.balance = sender.balance.saturating_add(total_debit);
            sender.transactions_today -= 1;
        }
        return HttpResponse::NotFound().json(serde_json::json!({"error": "Receiver not found"}));
    }

    HttpResponse::Ok().json(serde_json::json!({
        "status": "completed",
        "amount": req.amount,
        "fee": fee,
        "total_debited": total_debit
    }))
}

async fn create_withdrawal(
    data: web::Data<Arc<AppState>>,
    path: web::Path<String>,
    amount: web::Json<u64>,
) -> HttpResponse {
    let user_id = path.into_inner();
    let mut wallets = data.wallets.write().await;

    if let Some(account) = wallets.get_mut(&user_id) {
        let requested = amount.into_inner();
        let available = compute_available_balance(account);

        if available < requested {
            return HttpResponse::BadRequest().json(serde_json::json!({"error": "Insufficient funds"}));
        }

        account.pending_withdrawals = account.pending_withdrawals.saturating_add(requested);
        HttpResponse::Ok().json(serde_json::json!({"status": "withdrawal_pending", "amount": requested}))
    } else {
        HttpResponse::NotFound().json(serde_json::json!({"error": "User not found"}))
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let mut initial_wallets = HashMap::new();
    initial_wallets.insert("alice".to_string(), WalletAccount {
        user_id: "alice".to_string(),
        balance: 10000,
        pending_withdrawals: 0,
        daily_limit: 5000,
        transactions_today: 0,
    });
    initial_wallets.insert("bob".to_string(), WalletAccount {
        user_id: "bob".to_string(),
        balance: 5000,
        pending_withdrawals: 0,
        daily_limit: 5000,
        transactions_today: 0,
    });

    let state = Arc::new(AppState {
        wallets: RwLock::new(initial_wallets),
        fee_schedule: vec![50, 30, 20, 10], // basis points per tier
    });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/balance/{user_id}", web::get().to(get_balance))
            .route("/transfer", web::post().to(transfer))
            .route("/withdraw/{user_id}", web::post().to(create_withdrawal))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
